fn fibonacci(n: usize) -> Vec<i32> {
    // Handle small n explicitly, even though problem assumes n >= 2.
    if n == 0 {
        return Vec::new();
    }
    if n == 1 {
        return vec![0];
    }

    // We know n >= 2 here.
    let mut fibs = Vec::with_capacity(n);
    fibs.push(0);
    fibs.push(1);

    for i in 2..n {
        // Safe to index because we've already pushed at least two elements,
        // and we're growing fibs up to n elements.
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}

